export function LawCard(a,l=!1){return`<div class="law-card ${l?"selected":""}" data-id="${a.id}">\n    <div class="law-card-image">\n      <img src="${a.image}" alt="${a.name}" loading="lazy" />\n      <div class="law-card-overlay" style="border-left-color: ${a.color}">\n        <span class="law-year">${a.year}</span>\n      </div>\n    </div>\n    <div class="law-card-body">\n      <h3 class="law-card-name">${a.name}</h3>\n      <p class="law-card-summary">${a.summary}</p>\n      <button class="law-card-btn" data-id="${a.id}">\n        Learn more <span class="arrow">→</span>\n      </button>\n    </div>\n  </div>`}export function LawDetail(a){const l=a.keyFacts.map(a=>`<li>${a}</li>`).join("");return`<div class="law-detail" style="border-top-color: ${a.color}">\n    <div class="law-detail-header">\n      <h2>${a.name}</h2>\n      <span class="law-detail-year">${a.year}</span>\n    </div>\n    <p class="law-detail-summary">${a.summary}</p>\n    <h4>Key Facts</h4>\n    <ul class="law-detail-facts">${l}</ul>\n  </div>`}